:root[data-theme-id="sky-cloud"] [data-region="root"] {
  background:
    radial-gradient(circle at 76% 10%, rgba(255, 240, 161, 0.42), transparent 18%),
    radial-gradient(circle at 18% 4%, rgba(255,255,255,0.62), transparent 16%),
    linear-gradient(180deg, #66c6fa 0%, #aee5ff 38%, #eaf9ff 72%, #f8fdff 100%) !important;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"] {
  overflow: hidden;
  background:
    radial-gradient(circle at 78% 12%, rgba(255, 243, 180, 0.52), transparent 20%),
    radial-gradient(circle at 18% 6%, rgba(255,255,255,0.72), transparent 18%),
    linear-gradient(180deg, #66c6fa 0%, #b9eaff 44%, #f2fbff 100%) !important;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::before,
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::after {
  content: "";
  position: absolute;
  left: -24vw;
  width: 160vw;
  pointer-events: none;
  background-repeat: repeat-x;
  will-change: transform;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::before {
  bottom: -36px;
  height: 420px;
  opacity: 0.98;
  background-image: var(--sky-cloud-bank);
  background-size: 1420px 400px;
  filter: drop-shadow(0 22px 30px rgba(31, 122, 178, 0.18));
  animation: sky-background-bank 72s linear infinite;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::after {
  top: 18px;
  height: 300px;
  opacity: 0.54;
  background-image: var(--sky-cloud-wisps);
  background-size: 1040px 300px;
  filter: blur(0.2px);
  animation: sky-background-wisps 118s linear infinite reverse;
}
:root[data-theme-id="sky-cloud"] [data-region="main"] {
  isolation: isolate;
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.16), rgba(231,248,255,0.18)) !important;
  box-shadow: inset 1px 0 0 rgba(255,255,255,0.56);
}
:root[data-theme-id="sky-cloud"] [data-region="main"]::before,
:root[data-theme-id="sky-cloud"] [data-region="main"]::after {
  content: "";
  position: absolute;
  pointer-events: none;
  z-index: 0;
  background-repeat: repeat-x;
  will-change: transform;
}
:root[data-theme-id="sky-cloud"] [data-region="main"]::before {
  left: -18vw;
  bottom: -70px;
  width: 148vw;
  height: 340px;
  opacity: 0.72;
  background-image: var(--sky-cloud-bank);
  background-size: 1080px 314px;
  filter: drop-shadow(0 16px 20px rgba(31,122,178,0.12));
  animation: sky-main-cloud-bank 90s linear infinite;
}
:root[data-theme-id="sky-cloud"] [data-region="main"]::after {
  left: -12vw;
  top: 132px;
  width: 136vw;
  height: 240px;
  opacity: 0.22;
  background-image: var(--sky-cloud-wisps);
  background-size: 820px 236px;
  filter: blur(0.4px);
  animation: sky-main-wisps 128s linear infinite reverse;
}
:root[data-theme-id="sky-cloud"] [data-region="main"] > * {
  position: relative;
  z-index: 2;
}
:root[data-theme-id="sky-cloud"] [data-region="sidebar"] {
  isolation: isolate;
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.46), rgba(224,246,255,0.38)) !important;
  backdrop-filter: blur(22px) saturate(126%);
  box-shadow: inset -1px 0 0 rgba(255,255,255,0.52), 14px 0 36px rgba(31,122,178,0.08);
}
:root[data-theme-id="sky-cloud"] [data-region="sidebar"]::before {
  content: "";
  position: absolute;
  left: -84px;
  bottom: 116px;
  width: 390px;
  height: 170px;
  z-index: 0;
  pointer-events: none;
  opacity: 0.44;
  background-image: var(--sky-mini-cloud);
  background-size: contain;
  background-repeat: no-repeat;
  filter: drop-shadow(0 16px 18px rgba(31,122,178,0.12));
  animation: sky-sidebar-drift 38s ease-in-out infinite alternate;
}
:root[data-theme-id="sky-cloud"] [data-region="sidebar"] > * {
  position: relative;
  z-index: 2;
}
:root[data-theme-id="sky-cloud"] [data-region="searchbar"] {
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.70), rgba(222,246,255,0.48)) !important;
  border-bottom-color: rgba(95,176,222,0.30) !important;
  backdrop-filter: blur(20px) saturate(128%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.78), 0 18px 34px rgba(31,122,178,0.08);
}
:root[data-theme-id="sky-cloud"] [data-region="searchbar"]::before {
  content: "";
  position: absolute;
  right: 26px;
  bottom: -42px;
  width: 280px;
  height: 122px;
  z-index: 0;
  opacity: 0.42;
  pointer-events: none;
  background-image: var(--sky-mini-cloud);
  background-repeat: no-repeat;
  background-size: contain;
  animation: sky-search-cloud 20s ease-in-out infinite alternate;
}
:root[data-theme-id="sky-cloud"] [data-region="searchbar"] > * {
  position: relative;
  z-index: 2;
}
:root[data-theme-id="sky-cloud"] [data-region="filterbar"] {
  background: rgba(255,255,255,0.42) !important;
  backdrop-filter: blur(16px) saturate(120%);
  border-bottom-color: rgba(95,176,222,0.24) !important;
}
:root[data-theme-id="sky-cloud"] .surface-card,
:root[data-theme-id="sky-cloud"] .surface-card-soft,
:root[data-theme-id="sky-cloud"] .modal-surface,
:root[data-theme-id="sky-cloud"] .mod-panel-floating {
  border-color: var(--sky-glass-border) !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.66), rgba(232,248,255,0.48)) !important;
  backdrop-filter: blur(20px) saturate(124%);
  box-shadow:
    0 22px 58px rgba(31,122,178,0.13),
    inset 0 1px 0 var(--sky-glass-highlight),
    inset 0 -1px 0 rgba(139,211,246,0.18);
}
:root[data-theme-id="sky-cloud"] .item-card-render-scope {
  overflow: hidden;
  border-color: rgba(95,176,222,0.28) !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.70), rgba(235,249,255,0.54)) !important;
  backdrop-filter: blur(16px) saturate(122%);
  box-shadow:
    0 20px 50px rgba(31,122,178,0.12),
    inset 0 1px 0 rgba(255,255,255,0.78);
}
:root[data-theme-id="sky-cloud"] .item-card-render-scope::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.44;
  background:
    linear-gradient(135deg, rgba(255,255,255,0.72), transparent 38%),
    radial-gradient(circle at 88% 12%, rgba(160,222,255,0.34), transparent 22%);
}
:root[data-theme-id="sky-cloud"] .item-card-render-scope::after {
  content: "";
  position: absolute;
  right: -36px;
  bottom: -28px;
  width: 180px;
  height: 78px;
  pointer-events: none;
  opacity: 0.30;
  background-image: var(--sky-mini-cloud);
  background-repeat: no-repeat;
  background-size: contain;
  filter: drop-shadow(0 10px 12px rgba(31,122,178,0.10));
}
:root[data-theme-id="sky-cloud"] .item-row-render-scope {
  background: rgba(255,255,255,0.38) !important;
  backdrop-filter: blur(12px) saturate(120%);
}
:root[data-theme-id="sky-cloud"] .action-button,
:root[data-theme-id="sky-cloud"] .control-chip {
  border-color: rgba(95,176,222,0.28);
  background: rgba(255,255,255,0.56);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.78), 0 10px 22px rgba(31,122,178,0.08);
}
:root[data-theme-id="sky-cloud"] .action-button-primary,
:root[data-theme-id="sky-cloud"] .control-chip-active {
  background: linear-gradient(180deg, #32baf4, #0ea5e9) !important;
  color: white;
  border-color: rgba(255,255,255,0.58);
  box-shadow: 0 14px 30px rgba(14,165,233,0.24), inset 0 1px 0 rgba(255,255,255,0.46);
}
:root[data-theme-id="sky-cloud"] .empty-state-panel {
  position: relative;
  overflow: hidden;
  background: rgba(255,255,255,0.44) !important;
  backdrop-filter: blur(18px) saturate(122%);
}
