  left: 50%;
  bottom: -52px;
  width: 520px;
  height: 220px;
  transform: translateX(-50%);
  opacity: 0.48;
  pointer-events: none;
  background-image: var(--sky-cloud-bank);
  background-repeat: no-repeat;
  background-size: contain;
}
:root[data-theme-id="sky-cloud"] .text-label {
  color: #267fb1;
  text-shadow: 0 1px 0 rgba(255,255,255,0.62);
}
@keyframes sky-background-bank {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-1320px, 0, 0); }
}
@keyframes sky-background-wisps {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-980px, 0, 0); }
}
@keyframes sky-main-cloud-bank {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-980px, 0, 0); }
}
@keyframes sky-main-wisps {
  from { transform: translate3d(0, 0, 0); }
