@media (prefers-reduced-motion: reduce) {
  :root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::before,
  :root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::after,
  :root[data-theme-id="sky-cloud"] [data-region="main"]::before,
  :root[data-theme-id="sky-cloud"] [data-region="main"]::after,
  :root[data-theme-id="sky-cloud"] [data-region="sidebar"]::before,
  :root[data-theme-id="sky-cloud"] [data-region="searchbar"]::before {
    animation: none !important;
  }
}

/* Soft feathered cloud pass: keep clouds behind UI, make edges airy and translucent. */
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::before {
  opacity: 0.62;
  filter: blur(1.8px) saturate(108%) drop-shadow(0 28px 42px rgba(94, 174, 218, 0.14));
  mix-blend-mode: screen;
  mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.72) 18%, #000 58%, rgba(0,0,0,0.62) 78%, transparent 100%);
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.72) 18%, #000 58%, rgba(0,0,0,0.62) 78%, transparent 100%);
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::after {
  opacity: 0.34;
  filter: blur(3.2px) saturate(104%);
  mix-blend-mode: screen;
  mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.56) 22%, rgba(0,0,0,0.84) 55%, transparent 100%);
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.56) 22%, rgba(0,0,0,0.84) 55%, transparent 100%);
}
:root[data-theme-id="sky-cloud"] [data-region="main"]::before {
  opacity: 0.46;
  filter: blur(2.4px) saturate(108%) drop-shadow(0 20px 34px rgba(94, 174, 218, 0.12));
  mix-blend-mode: screen;
  mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.76) 20%, #000 68%, transparent 100%);
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.76) 20%, #000 68%, transparent 100%);
}
:root[data-theme-id="sky-cloud"] [data-region="main"]::after {
  opacity: 0.16;
  filter: blur(4px) saturate(102%);
  mix-blend-mode: screen;
}
:root[data-theme-id="sky-cloud"] [data-region="sidebar"]::before,
:root[data-theme-id="sky-cloud"] [data-region="searchbar"]::before,
:root[data-theme-id="sky-cloud"] .item-card-render-scope::after,
:root[data-theme-id="sky-cloud"] .empty-state-panel::before {
  filter: blur(1.2px) saturate(106%) drop-shadow(0 14px 22px rgba(94,174,218,0.12));
  mix-blend-mode: screen;
}
:root[data-theme-id="sky-cloud"] [data-region="sidebar"]::before { opacity: 0.28; }
:root[data-theme-id="sky-cloud"] [data-region="searchbar"]::before { opacity: 0.28; }
:root[data-theme-id="sky-cloud"] .item-card-render-scope::after { opacity: 0.20; }
:root[data-theme-id="sky-cloud"] .empty-state-panel::before { opacity: 0.32; }
